$ErrorActionPreference = 'Stop'
$root='D:\Projects\BuildingManagement-MVC';$resourceDir=Join-Path $root 'Resources';$viewDir=Join-Path $root 'Views'
$viewKeys=[System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
Get-ChildItem $viewDir -Recurse -File -Filter '*.cshtml' | ForEach-Object {$source=[IO.File]::ReadAllText($_.FullName);foreach($m in [regex]::Matches($source,'Loc\.(?:T|Js)\(\s*"([^"]+)"')){[void]$viewKeys.Add($m.Groups[1].Value)}}
function Load-Resource([string]$n){$d=[System.Xml.XmlDocument]::new();$d.Load((Join-Path $resourceDir $n));return $d}
function Get-Map($d){$m=@{};foreach($n in $d.SelectNodes('/root/data')){$v=$n.SelectSingleNode('value');if($null -ne $v){$m[$n.GetAttribute('name')]=$v.InnerText}};return $m}
function Add-Value($d,[string]$k,[string]$v){if($null -ne $d.SelectSingleNode("/root/data[@name='$k']")){return};$e=$d.CreateElement('data');$e.SetAttribute('name',$k);$a=$d.CreateAttribute('xml','space','http://www.w3.org/XML/1998/namespace');$a.Value='preserve';[void]$e.Attributes.Append($a);$n=$d.CreateElement('value');$n.InnerText=$v;[void]$e.AppendChild($n);[void]$d.DocumentElement.AppendChild($e)}
function Save-Resource($d,[string]$n){$s=[System.Xml.XmlWriterSettings]::new();$s.Encoding=[System.Text.UTF8Encoding]::new($false);$s.Indent=$true;$s.IndentChars='  ';$s.NewLineChars=[Environment]::NewLine;$s.NewLineHandling=[System.Xml.NewLineHandling]::Replace;$w=[System.Xml.XmlWriter]::Create((Join-Path $resourceDir $n),$s);try{$d.Save($w)}finally{$w.Dispose()}}
function Has-Value($o,[string]$k){return $null -ne $o.PSObject.Properties[$k]}
function Get-Value($o,[string]$k){return [string]$o.PSObject.Properties[$k].Value}
$neutral=Load-Resource 'Shared.resx';$english=Load-Resource 'Shared.en.resx';$nm=Get-Map $neutral;$em=Get-Map $english;$nadd=0
$fallbackEn=@{Exception='Exception';History='History';Phone_Number='Phone number';Reversed='Reversed';Select_Apartment='Select apartment'}
foreach($k in $fallbackEn.Keys){if(-not $nm.ContainsKey($k)){Add-Value $neutral $k $fallbackEn[$k];$nm[$k]=$fallbackEn[$k];$nadd++}}
foreach($k in $viewKeys){if(-not $nm.ContainsKey($k) -and $em.ContainsKey($k)){Add-Value $neutral $k $em[$k];$nm[$k]=$em[$k];$nadd++}}
if($nadd){Save-Resource $neutral 'Shared.resx'}
$eadd=0;foreach($k in $viewKeys){if(-not $em.ContainsKey($k) -and $nm.ContainsKey($k)){Add-Value $english $k $nm[$k];$eadd++}}
if($eadd){Save-Resource $english 'Shared.en.resx'}
$ar=ConvertFrom-Json -InputObject '{"Exception":"\u0627\u0633\u062a\u062b\u0646\u0627\u0621","History":"\u0627\u0644\u0633\u062c\u0644","Phone_Number":"\u0631\u0642\u0645 \u0627\u0644\u0647\u0627\u062a\u0641","Reversed":"\u0645\u0639\u0643\u0648\u0633","Select_Apartment":"\u0627\u062e\u062a\u0631 \u0627\u0644\u0634\u0642\u0629"}';$fr=ConvertFrom-Json -InputObject '{"All_Events":"Tous les \u00e9v\u00e9nements","All_Levels":"Tous les niveaux","Application_Logs":"Journaux de l\u2019application","Correlation_ID":"ID de corr\u00e9lation","Events":"\u00c9v\u00e9nements","Exception":"Exception","From_Date_UTC":"\u00c0 partir du (UTC)","History":"Historique","Invalid_Date_Range":"La date de d\u00e9but doit \u00eatre ant\u00e9rieure ou \u00e9gale \u00e0 la date de fin.","Level":"Niveau","Log_Activity":"ACTIVIT\u00c9","Log_Advanced_Filters":"Filtres avanc\u00e9s","Log_Center_Eyebrow":"OBSERVABILIT\u00c9 DE L\u2019APPLICATION","Log_Center_Subtitle":"Surveillez l\u2019activit\u00e9, examinez les erreurs et suivez les \u00e9v\u00e9nements de l\u2019application.","Log_Clear_Filters":"Effacer les filtres","Log_Current_Page":"Sur cette page","Log_Current_Page_Only":"Les compteurs concernent uniquement la page actuelle","Log_Dates_Are_UTC_And_Redacted":"Les dates sont en UTC. Les donn\u00e9es sensibles sont masqu\u00e9es avant affichage.","Log_Distinct_Sources":"Contextes sources distincts","Log_Empty_Title":"Aucun \u00e9v\u00e9nement \u00e0 afficher","Log_Error_Fatal":"Erreur / Critique","Log_Errors_On_Page":"Erreurs sur la page","Log_Exceptions_On_Page":"Exceptions sur la page","Log_Explore":"EXPLORER","Log_Filter_By_Correlation":"Rechercher tous les \u00e9v\u00e9nements avec cet ID de corr\u00e9lation","Log_Information":"Information","Log_Inspect":"Examiner","Log_Of":"sur","Log_Overview":"Vue d\u2019ensemble des journaux","Log_Results":"\u00c9v\u00e9nements du journal","Log_Results_Description":"\u00c9v\u00e9nements applicatifs assainis correspondant \u00e0 vos crit\u00e8res.","Log_Search_Anything":"Rechercher dans les journaux","Log_Search_Placeholder":"Rechercher des messages, exceptions ou d\u00e9tails\u2026","Log_Source_Placeholder":"Espace de noms ou composant","Log_Sources_On_Page":"Sources sur la page","Log_Total_Matching":"Total des \u00e9v\u00e9nements correspondants","Log_UTC_Time":"Horodatage (UTC)","Log_Visible_On_Page":"\u00c9v\u00e9nements visibles","Log_Warnings":"Avertissements","Log_With_Exception":"\u00c9v\u00e9nements avec exception","Message":"Message","No_Log_Events_Found":"Aucun \u00e9v\u00e9nement ne correspond aux filtres s\u00e9lectionn\u00e9s.","Phone_Correction_Requests":"Demandes de correction du t\u00e9l\u00e9phone","Phone_Number":"Num\u00e9ro de t\u00e9l\u00e9phone","PIN_4_12_Digits":"Le code PIN doit contenir de 4 \u00e0 12 chiffres.","Resident_Change_PIN":"Modification du code PIN du r\u00e9sident","Reversed":"Contrepass\u00e9","Save_New_PIN":"Enregistrer le nouveau PIN","Select_Apartment":"S\u00e9lectionner un appartement","Source_Context":"Source","Temporary_PIN_1234_Not_Allowed":"Le PIN temporaire 1234 n\u2019est pas autoris\u00e9.","Temporary_PIN_Replace_Notice":"Remplacez le PIN temporaire par un code personnel et confidentiel.","To_Date_UTC":"Jusqu\u2019au (UTC)","With_Exception":"Avec exception","Without_Exception":"Sans exception"}';$de=ConvertFrom-Json -InputObject '{"All_Events":"Alle Ereignisse","All_Levels":"Alle Ebenen","Application_Logs":"Anwendungsprotokolle","Correlation_ID":"Korrelations-ID","Events":"Ereignisse","Exception":"Ausnahme","From_Date_UTC":"Von-Datum (UTC)","History":"Verlauf","Invalid_Date_Range":"Das Startdatum darf nicht nach dem Enddatum liegen.","Level":"Ebene","Log_Activity":"AKTIVIT\u00c4T","Log_Advanced_Filters":"Erweiterte Filter","Log_Center_Eyebrow":"ANWENDUNGS\u00dcBERWACHUNG","Log_Center_Subtitle":"\u00dcberwachen Sie Laufzeitaktivit\u00e4ten, untersuchen Sie Fehler und verfolgen Sie Anwendungsereignisse.","Log_Clear_Filters":"Filter zur\u00fccksetzen","Log_Current_Page":"Auf dieser Seite","Log_Current_Page_Only":"Die Z\u00e4hler beziehen sich nur auf die aktuelle Seite","Log_Dates_Are_UTC_And_Redacted":"Datumsangaben verwenden UTC. Sensible Werte werden vor der Anzeige maskiert.","Log_Distinct_Sources":"Unterschiedliche Quellkontexte","Log_Empty_Title":"Keine Ereignisse vorhanden","Log_Error_Fatal":"Fehler / Schwerwiegend","Log_Errors_On_Page":"Fehler auf der Seite","Log_Exceptions_On_Page":"Ausnahmen auf der Seite","Log_Explore":"ERKUNDEN","Log_Filter_By_Correlation":"Alle Ereignisse mit dieser Korrelations-ID suchen","Log_Information":"Information","Log_Inspect":"Pr\u00fcfen","Log_Of":"von","Log_Overview":"Protokoll\u00fcbersicht","Log_Results":"Protokollereignisse","Log_Results_Description":"Bereinigte Anwendungsereignisse, die Ihren Suchkriterien entsprechen.","Log_Search_Anything":"Protokolle durchsuchen","Log_Search_Placeholder":"Nach Nachrichten, Ausnahmen oder Details suchen\u2026","Log_Source_Placeholder":"Namespace oder Komponentenname","Log_Sources_On_Page":"Quellen auf der Seite","Log_Total_Matching":"\u00dcbereinstimmende Ereignisse insgesamt","Log_UTC_Time":"Zeitstempel (UTC)","Log_Visible_On_Page":"Sichtbare Ereignisse","Log_Warnings":"Warnungen","Log_With_Exception":"Ereignisse mit Ausnahme","Message":"Nachricht","No_Log_Events_Found":"Keine Protokollereignisse entsprechen den ausgew\u00e4hlten Filtern.","Phone_Correction_Requests":"Antr\u00e4ge zur Korrektur der Telefonnummer","Phone_Number":"Telefonnummer","PIN_4_12_Digits":"Die PIN muss aus 4 bis 12 Ziffern bestehen.","Resident_Change_PIN":"PIN-\u00c4nderung des Bewohners","Reversed":"Storniert","Save_New_PIN":"Neue PIN speichern","Select_Apartment":"Wohnung ausw\u00e4hlen","Source_Context":"Quelle","Temporary_PIN_1234_Not_Allowed":"Die tempor\u00e4re PIN 1234 ist nicht zul\u00e4ssig.","Temporary_PIN_Replace_Notice":"Ersetzen Sie die tempor\u00e4re PIN durch eine pers\u00f6nliche, vertrauliche PIN.","To_Date_UTC":"Bis-Datum (UTC)","With_Exception":"Mit Ausnahme","Without_Exception":"Ohne Ausnahme"}'
foreach($spec in @(@{Name='Shared.ar.resx';Map=$ar},@{Name='Shared.fr.resx';Map=$fr},@{Name='Shared.de.resx';Map=$de})){
 $d=Load-Resource $spec.Name;$m=Get-Map $d;$added=0
 foreach($k in $viewKeys){if(-not $m.ContainsKey($k)){if(Has-Value $spec.Map $k){$v=Get-Value $spec.Map $k}elseif($nm.ContainsKey($k)){$v=$nm[$k]}else{throw "Missing fallback $k in $($spec.Name)"};Add-Value $d $k $v;$added++}}
 if($added){Save-Resource $d $spec.Name};Write-Output "$($spec.Name): added $added view keys"
}
Write-Output "Shared.resx added $nadd; Shared.en.resx added $eadd; literal view keys=$($viewKeys.Count)"
